inline QJsonObject version(QJsonObject draft,QString savedAt){auto sc=draft.value("scope").toObject();QJsonObject r{{"schema","portfolio-mirror-record/v1"},{"kind","mirror"},{"accountId",sc.value("account").toObject().value("id")},{"seriesId",hash(QJsonObject{{"accountId",sc.value("account").toObject().value("id")},{"sourceLabel",draft.value("mirror").toObject().value("sourceLabel")},{"accountRef",draft.value("mirror").toObject().value("accountRef")}})},{"savedAt",time(savedAt)},{"draft",draft}};r["id"]=hash(r);return r;}
inline QJsonObject validateRecord(QJsonObject r){depth(r);need(r.value("schema")=="portfolio-mirror-record/v1"&&QStringList{"mirror","comparison"}.contains(r.value("kind").toString())&&!r.value("accountId").toString().isEmpty(),"镜像版本身份无效");auto unsignedRecord=r;auto id=unsignedRecord.take("id");need(id.isString()&&id.toString()==hash(unsignedRecord),"版本内容指纹不一致");time(r.value("savedAt").toString());if(r.value("kind")=="mirror"){auto d=r.value("draft").toObject();auto source=d.value("source").toObject();need(decode(source.value("rawUtf8").toString().toUtf8())==source,"原文件与解析快照不一致");need(hash(d.value("scope"))==d.value("scopeFingerprint").toString(),"冻结只读快照指纹不一致");need(reconcile(d.value("mirror").toObject(),d.value("scope").toObject())==d.value("reconciliation").toObject(),"差异证据与冻结输入不一致");auto sc=d.value("scope").toObject();QJsonObject context{{"accounts",QJsonArray{sc.value("account")}}, {"ledgers",QJsonArray{sc.value("ledger")}}, {"instruments",sc.value("instruments")}, {"capturedAt",sc.value("capturedAt")},{"sourceLabel",sc.value("sourceLabel")}};auto reproduced=prepare(source,d.value("mirror").toObject().value("snapshotIndex").toInt(-1),context,r.value("accountId").toString(),d.value("bindings").toArray(),d.value("options").toObject());need(reproduced==d,"绑定后的镜像字段与原源文件/依据不一致");}else need(r.value("mirrorId").isString()&&reconcile(r.value("mirror").toObject(),r.value("scope").toObject())==r.value("reconciliation").toObject(),"对账证据不一致");return r;}
inline QJsonObject comparison(QJsonObject mirrorRecord,QJsonObject input,QString savedAt){validateRecord(mirrorRecord);need(mirrorRecord.value("kind")=="mirror","需选择镜像版本");auto m=mirrorRecord.value("draft").toObject().value("mirror").toObject();QJsonArray ids;for(auto v:m.value("holdings").toArray())ids.append(v.toObject().value("instrumentId"));auto sc=scope(input,mirrorRecord.value("accountId").toString(),ids);auto oldDraft=mirrorRecord.value("draft").toObject();continuity(oldDraft.value("scope").toObject().value("account").toObject(),sc.value("account").toObject());accountBinding(m.value("accountRef").toObject(),sc.value("account").toObject(),input,oldDraft.value("options").toObject().value("accountBindingReason").toString());QJsonObject r{{"schema","portfolio-mirror-record/v1"},{"kind","comparison"},{"accountId",mirrorRecord.value("accountId")},{"seriesId",mirrorRecord.value("seriesId")},{"mirrorId",mirrorRecord.value("id")},{"savedAt",time(savedAt)},{"mirror",m},{"scope",sc},{"reconciliation",reconcile(m,sc)}};r["id"]=hash(r);return r;}
